css:
/* ============================================================
   COMPLETE PRODUCTION CSS — Go Vegan
   ============================================================ */

/* ---------- Reset & Base ---------- */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
  -moz-text-size-adjust: 100%;
  text-size-adjust: 100%;
  background-color: var(--bg-body);
  color: var(--text-primary);
}

body {
  font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  line-height: 1.6;
  min-height: 100vh;
  background: var(--bg-body);
  color: var(--text-primary);
  transition: background 0.25s, color 0.25s;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  padding-top: env(safe-area-inset-top, 0px);
}

img,
svg {
  display: block;
  max-width: 100%;
}

button,
input,
textarea {
  font: inherit;
}

button {
  color: inherit;
}

/* ---------- Themes ---------- */
:root {
  --font-display: Georgia, "Times New Roman", serif;
  --font-body: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Consolas, monospace;

  /* Light defaults (also used as fallback) */
  --bg-body: #f7f2e8;
  --bg-surface: #fffdf7;
  --bg-surface-alt: #f3efe6;
  --bg-elevated: #ffffff;
  --bg-input: #f7f2e8;
  --bg-header: rgba(255, 253, 247, 0.92);
  --bg-overlay: rgba(0, 0, 0, 0.35);
  --text-primary: #111111;
  --text-secondary: #46574e;
  --text-muted: #7a8a7e;
  --text-inverse: #f5f0e4;
  --color-forest: #123c2e;
  --color-forest-hover: #1a5a44;
  --color-moss: #6d8b61;
  --color-moss-hover: #5a784e;
  --color-lime: #b8e14b;
  --color-lime-hover: #c8ea5a;
  --color-coral: #e98269;
  --border-subtle: #ded8ca;
  --border-strong: #c5bda8;
  --shadow-sm: 0 2px 8px rgba(18, 60, 46, 0.06);
  --shadow-md: 0 8px 28px rgba(18, 60, 46, 0.08);
  --shadow-lg: 0 16px 48px rgba(18, 60, 46, 0.10);
  --shadow-modal: 0 24px 64px rgba(18, 60, 46, 0.16);
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-full: 9999px;
  --header-blur: blur(12px);
}

[data-theme="light"] {
  --bg-body: #f7f2e8;
  --bg-surface: #fffdf7;
  --bg-surface-alt: #f3efe6;
  --bg-elevated: #ffffff;
  --bg-input: #f7f2e8;
  --bg-header: rgba(255, 253, 247, 0.92);
  --bg-overlay: rgba(0, 0, 0, 0.35);
  --text-primary: #111111;
  --text-secondary: #46574e;
  --text-muted: #7a8a7e;
  --text-inverse: #f5f0e4;
  --color-forest: #123c2e;
  --color-forest-hover: #1a5a44;
  --color-moss: #6d8b61;
  --color-moss-hover: #5a784e;
  --color-lime: #b8e14b;
  --color-lime-hover: #c8ea5a;
  --color-coral: #e98269;
  --border-subtle: #ded8ca;
  --border-strong: #c5bda8;
  --shadow-sm: 0 2px 8px rgba(18, 60, 46, 0.06);
  --shadow-md: 0 8px 28px rgba(18, 60, 46, 0.08);
  --shadow-lg: 0 16px 48px rgba(18, 60, 46, 0.10);
  --shadow-modal: 0 24px 64px rgba(18, 60, 46, 0.16);
}

[data-theme="dark"] {
  --bg-body: #1a1e1b;
  --bg-surface: #242a26;
  --bg-surface-alt: #2d342f;
  --bg-elevated: #1e241f;
  --bg-input: #2d342f;
  --bg-header: rgba(36, 42, 38, 0.94);
  --bg-overlay: rgba(0, 0, 0, 0.6);
  --text-primary: #ffffff;
  --text-secondary: #b8c4b8;
  --text-muted: #8a9a8a;
  --text-inverse: #1a1e1b;
  --color-forest: #7aaa7a;
  --color-forest-hover: #9ac89a;
  --color-moss: #8fbc8f;
  --color-moss-hover: #a8d0a8;
  --color-lime: #b8e14b;
  --color-lime-hover: #c8ea5a;
  --color-coral: #e98269;
  --border-subtle: #3d4a3d;
  --border-strong: #5a6b5a;
  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 8px 28px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 16px 48px rgba(0, 0, 0, 0.5);
  --shadow-modal: 0 24px 64px rgba(0, 0, 0, 0.6);
}

/* ---------- Alpine Cloak ---------- */
[x-cloak] {
  display: none !important;
}

/* ---------- Focus ---------- */
*:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

/* ---------- Selection ---------- */
::selection {
  background: var(--color-lime);
  color: #000;
}

/* ---------- Scrollbar ---------- */
@media (pointer: fine) {
  ::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }
  ::-webkit-scrollbar-track {
    background: var(--bg-body);
  }
  ::-webkit-scrollbar-thumb {
    background: var(--border-strong);
    border-radius: 8px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: var(--color-moss);
  }
}

/* ---------- Typography ---------- */
h1, h2, h3, h4, h5, .font-display {
  font-family: var(--font-display);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.01em;
  color: var(--text-primary);
}

/* ---------- Layout & Containers ---------- */
.app-shell {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  max-width: 100vw;
  overflow-x: hidden;
}

.main-content {
  flex: 1;
  padding-bottom: calc(4.5rem + env(safe-area-inset-bottom, 0px));
}

@media (min-width: 1024px) {
  .main-content {
    padding-bottom: 0;
  }
}

.container,
.section-container,
.view-container {
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 1.25rem;
  padding-right: 1.25rem;
}

.view-container-narrow {
  max-width: 860px;
}

@media (min-width: 640px) {
  .container,
  .section-container,
  .view-container {
    padding-left: 2rem;
    padding-right: 2rem;
  }
}

@media (min-width: 1280px) {
  .container,
  .section-container,
  .view-container {
    padding-left: 2.5rem;
    padding-right: 2.5rem;
  }
}

/* ---------- Header ---------- */
.app-header {
  position: sticky;
  top: 0;
  z-index: 40;
  background: var(--bg-header);
  backdrop-filter: var(--header-blur);
  -webkit-backdrop-filter: var(--header-blur);
  border-bottom: 1px solid var(--border-subtle);
  transition: background 0.25s, border-color 0.25s;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1440px;
  margin: 0 auto;
  padding: 0.75rem 1.25rem;
  gap: 1rem;
}

@media (min-width: 640px) {
  .header-inner {
    padding-left: 2rem;
    padding-right: 2rem;
  }
}

@media (min-width: 1280px) {
  .header-inner {
    padding-left: 2.5rem;
    padding-right: 2.5rem;
  }
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  text-decoration: none;
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-forest);
  flex-shrink: 0;
}

.brand-icon {
  font-size: 1.5rem;
  line-height: 1;
}

.brand-name {
  color: var(--text-primary);
}

/* ---------- Desktop Navigation ---------- */
.desktop-navigation {
  display: none;
  align-items: center;
  gap: 1.75rem;
  font-size: 0.9rem;
  font-weight: 500;
}

.desktop-navigation a {
  color: var(--text-secondary);
  text-decoration: none;
  padding: 0.25rem 0;
  position: relative;
  transition: color 0.2s;
  cursor: pointer;
  white-space: nowrap;
  min-height: 2.75rem;
  display: flex;
  align-items: center;
}

.desktop-navigation a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--color-forest);
  transition: width 0.25s ease;
}

.desktop-navigation a:hover,
.desktop-navigation a.active {
  color: var(--text-primary);
}

.desktop-navigation a.active::after {
  width: 100%;
}

.desktop-more-wrap {
  position: relative;
  display: inline-block;
}

.nav-more-btn {
  background: none;
  border: none;
  font-family: var(--font-body);
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  padding: 0 0.25rem;
  transition: color 0.2s;
  appearance: none;
  min-height: 2.75rem;
  display: flex;
  align-items: center;
}

.nav-more-btn:hover {
  color: var(--text-primary);
}

.desktop-more-menu {
  position: absolute;
  right: 0;
  top: calc(100% + 0.5rem);
  min-width: 200px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  padding: 0.5rem 0;
  z-index: 50;
}

.menu-item {
  display: block;
  width: 100%;
  text-align: left;
  padding: 0.6rem 1.25rem;
  background: none;
  border: none;
  font-family: var(--font-body);
  font-size: 0.9rem;
  color: var(--text-secondary);
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
  appearance: none;
  min-height: 2.75rem;
  text-decoration: none;
}

.menu-item:hover {
  background: var(--bg-surface-alt);
  color: var(--text-primary);
}

@media (min-width: 1024px) {
  .desktop-navigation {
    display: flex;
  }
}

/* ---------- Header Actions ---------- */
.header-actions {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  flex-shrink: 0;
}

.icon-button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: var(--radius-full);
  border: none;
  background: none;
  color: var(--text-secondary);
  font-size: 1.25rem;
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
  position: relative;
  appearance: none;
  flex-shrink: 0;
  text-decoration: none;
}

.icon-button:hover {
  background: var(--bg-surface-alt);
  color: var(--text-primary);
}

.favorites-badge {
  position: absolute;
  top: -2px;
  right: -2px;
  background: var(--color-coral);
  color: #fff;
  font-size: 0.6rem;
  font-weight: 700;
  min-width: 1.25rem;
  height: 1.25rem;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 0.25rem;
  line-height: 1;
}

.theme-toggle {
  font-size: 1.15rem;
}

/* ---------- Global Search ---------- */
.global-search {
  position: relative;
  padding: 0.5rem 1.25rem 1rem;
  max-width: 1440px;
  margin: 0 auto;
  z-index: 45;
}

@media (min-width: 640px) {
  .global-search {
    padding-left: 2rem;
    padding-right: 2rem;
  }
}

@media (min-width: 1280px) {
  .global-search {
    padding-left: 2.5rem;
    padding-right: 2.5rem;
  }
}

.search-field {
  position: relative;
  display: flex;
  align-items: center;
  background: var(--bg-input);
  border: 1.5px solid var(--border-subtle);
  border-radius: var(--radius-full);
  padding: 0.25rem;
  transition: border-color 0.2s, box-shadow 0.2s;
  min-height: 3.25rem;
}

.search-field:focus-within {
  border-color: var(--color-moss);
  box-shadow: 0 0 0 3px rgba(109, 139, 97, 0.15);
}

.search-icon {
  flex-shrink: 0;
  padding: 0 0.75rem 0 1rem;
  font-size: 1rem;
  color: var(--text-muted);
  line-height: 1;
}

.search-input {
  flex: 1;
  min-width: 0;
  border: none;
  background: transparent;
  padding: 0.6rem 0;
  font-size: 1rem;
  font-family: var(--font-body);
  color: var(--text-primary);
  outline: none;
}

.search-input::placeholder {
  color: var(--text-muted);
}

.search-clear {
  flex-shrink: 0;
  padding: 0 0.75rem;
  font-size: 1rem;
  color: var(--text-muted);
  background: none;
  border: none;
  cursor: pointer;
  transition: color 0.2s;
  line-height: 1;
  appearance: none;
  min-height: 2.75rem;
  min-width: 2.75rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.search-clear:hover {
  color: var(--text-primary);
}

.search-submit {
  flex-shrink: 0;
  border-radius: var(--radius-full);
  padding: 0.4rem 1.25rem;
  font-size: 0.95rem;
  margin-left: 0.25rem;
  min-height: 2.75rem;
}

.search-results {
  margin-top: 0.75rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  padding: 0.75rem;
  max-height: 320px;
  overflow-y: auto;
  position: relative;
  z-index: 50;
}

.search-result-group {
  margin-bottom: 1rem;
}

.search-result-group:last-child {
  margin-bottom: 0;
}

.search-result-group h4 {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
  margin-bottom: 0.4rem;
  padding-bottom: 0.25rem;
  border-bottom: 1px solid var(--border-subtle);
  font-family: var(--font-body);
  font-weight: 600;
}

.search-result-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-sm);
  background: none;
  border: none;
  font-family: var(--font-body);
  font-size: 0.9rem;
  color: var(--text-secondary);
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
  text-align: left;
  appearance: none;
  min-height: 2.75rem;
}

.search-result-item:hover {
  background: var(--bg-surface-alt);
  color: var(--text-primary);
}

.search-empty {
  text-align: center;
  padding: 1.5rem 0;
  color: var(--text-muted);
  font-size: 0.9rem;
}

/* ---------- Buttons ---------- */
.primary-button {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.7rem 2rem;
  background: var(--color-forest);
  color: var(--text-inverse);
  border: none;
  border-radius: var(--radius-full);
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: background 0.2s, transform 0.15s, box-shadow 0.2s;
  box-shadow: var(--shadow-sm);
  text-decoration: none;
  appearance: none;
  min-height: 3rem;
  min-width: 3rem;
  justify-content: center;
}

.primary-button:hover {
  background: var(--color-forest-hover);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.primary-button:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: 2px;
}

.primary-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none !important;
  box-shadow: var(--shadow-sm);
}

.primary-button:disabled:hover {
  background: var(--color-forest);
  transform: none;
  box-shadow: var(--shadow-sm);
}

[data-theme="dark"] .primary-button {
  background: var(--color-forest);
  color: var(--text-inverse);
}

[data-theme="dark"] .primary-button:hover {
  background: var(--color-forest-hover);
}

.secondary-button {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.7rem 2rem;
  background: transparent;
  color: var(--text-primary);
  border: 1.5px solid var(--border-strong);
  border-radius: var(--radius-full);
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, transform 0.15s;
  text-decoration: none;
  appearance: none;
  min-height: 3rem;
  min-width: 3rem;
  justify-content: center;
}

.secondary-button:hover {
  background: var(--bg-surface-alt);
  border-color: var(--color-forest);
}

.secondary-button:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: 2px;
}

.secondary-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none !important;
}

.secondary-button:disabled:hover {
  background: transparent;
  border-color: var(--border-strong);
  transform: none;
}

.text-button {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  background: none;
  border: none;
  font-family: var(--font-body);
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--color-moss);
  cursor: pointer;
  transition: color 0.2s;
  appearance: none;
  padding: 0.5rem 0.25rem;
  min-height: 2.75rem;
}

.text-button:hover {
  color: var(--color-forest);
  text-decoration: underline;
}

/* ---------- Filter Chips ---------- */
.filter-chip {
  display: inline-flex;
  align-items: center;
  padding: 0.4rem 1rem;
  border-radius: var(--radius-full);
  font-size: 0.8rem;
  font-weight: 500;
  background: var(--bg-surface-alt);
  color: var(--text-secondary);
  border: 1.5px solid var(--border-subtle);
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
  font-family: var(--font-body);
  appearance: none;
  min-height: 2.75rem;
}

.filter-chip:hover {
  border-color: var(--border-strong);
  color: var(--text-primary);
}

.filter-chip:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: 2px;
}

.filter-chip.active {
  background: var(--color-forest);
  color: var(--text-inverse);
  border-color: var(--color-forest);
}

[data-theme="dark"] .filter-chip.active {
  background: var(--color-forest);
  color: var(--text-inverse);
  border-color: var(--color-forest);
}

.filter-chip:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.filter-clear {
  background: transparent;
  color: var(--color-coral);
  border-color: var(--border-subtle);
}

.filter-clear:hover {
  border-color: var(--color-coral);
  color: var(--color-coral);
}

.filter-clear.active {
  background: var(--color-coral);
  color: #fff;
  border-color: var(--color-coral);
}

/* ---------- Tabs ---------- */
.tab-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  border-bottom: 1px solid var(--border-subtle);
  padding-bottom: 0.25rem;
  margin-top: 1.5rem;
  margin-bottom: 1.5rem;
}

.tab-button {
  padding: 0.4rem 1.25rem;
  border-radius: var(--radius-full);
  border: none;
  background: none;
  font-family: var(--font-body);
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.2s;
  appearance: none;
  white-space: nowrap;
  min-height: 2.75rem;
  display: inline-flex;
  align-items: center;
}

.tab-button:hover {
  background: var(--bg-surface-alt);
  color: var(--text-primary);
}

.tab-button.active {
  background: var(--color-forest);
  color: var(--text-inverse);
}

[data-theme="dark"] .tab-button.active {
  background: var(--color-forest);
  color: var(--text-inverse);
}

/* ---------- Section Utilities ---------- */
.section {
  padding: 3rem 0;
}

.section-swaps {
  background: var(--bg-surface);
}

.section-comparison {
  background: var(--bg-surface-alt);
}

.section-featured {
  background: var(--bg-surface);
}

.section-resources {
  background: var(--bg-surface-alt);
}

.section-features {
  background: var(--bg-surface);
}

.section-cta {
  background: var(--bg-surface-alt);
  border-top: 1px solid var(--border-subtle);
}

.section:not(:last-child) {
  border-bottom: 1px solid var(--border-subtle);
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}

.section-title {
  font-family: var(--font-display);
  font-size: 1.75rem;
  color: var(--text-primary);
}

@media (min-width: 640px) {
  .section-title {
    font-size: 2rem;
  }
}

.section-subtitle {
  color: var(--text-secondary);
  margin-top: 0.25rem;
  margin-bottom: 1.5rem;
}

/* ---------- Hero ---------- */
.hero {
  padding: 2.5rem 0;
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-subtle);
}

@media (min-width: 768px) {
  .hero {
    padding: 3rem 0;
  }
}

@media (min-width: 1024px) {
  .hero {
    padding: 4rem 0;
  }
}

.hero-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 1.25rem;
}

.hero-layout > * {
  min-width: 0;
}

@media (min-width: 1024px) {
  .hero-layout {
    grid-template-columns: 1fr 1fr;
    gap: 3rem;
    align-items: center;
  }
}

@media (min-width: 1280px) {
  .hero-layout {
    gap: 4rem;
    padding: 0 2.5rem;
  }
}

.hero-copy {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.hero-headline {
  font-family: var(--font-display);
  font-size: clamp(2rem, 5vw, 4.5rem);
  line-height: 1.1;
  color: var(--text-primary);
  max-width: 14ch;
}

.hero-subhead {
  font-size: clamp(1rem, 1.5vw, 1.35rem);
  color: var(--text-secondary);
  max-width: 40ch;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 0.5rem;
}

@media (max-width: 479px) {
  .hero-actions .primary-button,
  .hero-actions .secondary-button {
    width: 100%;
    justify-content: center;
  }
}

.hero-search {
  margin-top: 0.5rem;
}

.hero-search .search-field {
  background: var(--bg-elevated);
}

@media (max-width: 479px) {
  .hero-search .search-field {
    flex-wrap: wrap;
    border-radius: var(--radius-md);
    padding: 0.5rem;
    background: var(--bg-elevated);
  }
  .hero-search .search-input {
    flex: 1 1 100%;
    padding: 0.5rem 0;
  }
  .hero-search .search-submit {
    flex: 1 1 100%;
    margin-left: 0;
    justify-content: center;
    margin-top: 0.25rem;
  }
}

.hero-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.75rem;
}

.hero-tags .tag {
  cursor: pointer;
  transition: border-color 0.2s, background 0.2s;
}

.hero-tags .tag:hover {
  border-color: var(--color-moss);
  background: var(--bg-surface-alt);
}

/* ---------- Hero Visual / Artwork ---------- */
.hero-visual {
  width: min(100%, 680px);
  min-width: 0;
  justify-self: center;
}

.hero-image {
  display: block;
  width: 100%;
  height: clamp(320px, 36vw, 520px);
  object-fit: cover;
  object-position: center;
  border-radius: 24px;
  box-shadow: var(--shadow-lg);
}

@media (min-width: 600px) and (max-width: 1023px) {
  .hero-visual {
    width: min(100%, 520px);
  }

  .hero-image {
    height: 320px;
  }
}

/* ---------- Swap Grid ---------- */
.swap-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

.swap-grid > * {
  min-width: 0;
}

@media (min-width: 600px) {
  .swap-grid {
    gap: 1.25rem;
  }
}

@media (min-width: 1024px) {
  .swap-grid {
    grid-template-columns: repeat(5, 1fr);
    gap: 1.5rem;
  }
}

.swap-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-end;
  padding: 1.25rem;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;
  min-height: 130px;
  text-align: left;
  width: 100%;
  font-family: var(--font-body);
  color: var(--text-primary);
  appearance: none;
}

.swap-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: var(--color-moss);
}

.swap-card:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: 2px;
}

.swap-icon {
  font-size: 2rem;
  line-height: 1;
  margin-bottom: 0.5rem;
}

.swap-label {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 600;
}

.swap-action {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
}

/* ---------- Comparison ---------- */
.comparison-grid {
  display: grid;
  gap: 1.5rem;
}

.comparison-grid > * {
  min-width: 0;
}

@media (min-width: 1024px) {
  .comparison-grid {
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
    align-items: center;
  }
}

.comparison-card {
  padding: 2rem 1.5rem;
  text-align: center;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-subtle);
  background: var(--bg-surface-alt);
}

.comparison-target {
  background: rgba(184, 225, 75, 0.12);
  border-color: var(--color-lime);
}

[data-theme="dark"] .comparison-target {
  background: rgba(184, 225, 75, 0.08);
}

.comparison-icon {
  font-size: 3rem;
  line-height: 1;
  display: block;
  margin-bottom: 0.5rem;
}

.comparison-title {
  font-family: var(--font-display);
  font-size: 1.5rem;
  color: var(--text-primary);
}

.comparison-desc {
  color: var(--text-secondary);
  margin-top: 0.25rem;
}

.comparison-arrow {
  display: block;
  font-size: 2rem;
  margin-top: 0.75rem;
  color: var(--color-moss);
}

.comparison-tags {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.5rem;
  margin: 1rem 0;
}

/* ---------- Features Grid ---------- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
}

.features-grid > * {
  min-width: 0;
}

@media (min-width: 600px) {
  .features-grid {
    gap: 1rem;
  }
}

@media (min-width: 1024px) {
  .features-grid {
    grid-template-columns: repeat(6, 1fr);
    gap: 1rem;
  }
}

.feature-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 1.25rem 0.5rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;
  text-align: center;
  min-height: 100px;
  font-family: var(--font-body);
  color: var(--text-primary);
  appearance: none;
}

.feature-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-sm);
  border-color: var(--color-moss);
}

.feature-card:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: 2px;
}

.feature-icon {
  font-size: 2rem;
  line-height: 1;
  display: block;
}

.feature-label {
  font-family: var(--font-display);
  font-size: 0.85rem;
  margin-top: 0.25rem;
  color: var(--text-primary);
}

/* ---------- Resources ---------- */
.resources-grid {
  display: grid;
  gap: 1.5rem;
}

.resources-grid > * {
  min-width: 0;
}

@media (min-width: 768px) {
  .resources-grid {
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
  }
}

.resource-card {
  padding: 1.5rem;
  background: var(--bg-surface);
  border-radius: var(--radius-md);
  border: 1px solid var(--border-subtle);
}

.resource-title {
  font-family: var(--font-display);
  font-size: 1.35rem;
  color: var(--text-primary);
}

.resource-desc {
  color: var(--text-secondary);
  margin-top: 0.25rem;
  font-size: 0.95rem;
}

.resource-list {
  list-style: none;
  padding: 0;
  margin: 1rem 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  color: var(--text-secondary);
  font-size: 0.95rem;
}

.resource-list li {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.bullet {
  color: var(--color-lime);
  font-size: 0.6rem;
}

.resource-links {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-top: 1rem;
}

.resource-link {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.6rem 1rem;
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  text-decoration: none;
  color: var(--text-secondary);
  font-family: var(--font-body);
  font-size: 0.9rem;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, color 0.2s;
  appearance: none;
  width: 100%;
  text-align: left;
  min-height: 2.75rem;
}

.resource-link:hover {
  background: var(--bg-surface);
  border-color: var(--color-moss);
  color: var(--text-primary);
}

.resource-link:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: 2px;
}

/* ---------- CTA ---------- */
.section-cta {
  text-align: center;
  padding: 4rem 0;
  border-top: 1px solid var(--border-subtle);
}

.cta-title {
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 4vw, 3rem);
  color: var(--text-primary);
}

.cta-sub {
  color: var(--text-secondary);
  font-size: 1.05rem;
  margin-top: 0.5rem;
  margin-bottom: 1.5rem;
}

/* ---------- View Pages ---------- */
.view {
  padding: 2rem 0;
}

@media (min-width: 768px) {
  .view {
    padding: 3rem 0;
  }
}

.view-title {
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 3vw, 2.75rem);
  color: var(--text-primary);
}

.view-subtitle {
  color: var(--text-secondary);
  margin-top: 0.25rem;
  font-size: 1rem;
}

/* ---------- Favorites Header ---------- */
.favorites-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.favorites-header .view-title {
  margin-bottom: 0;
}

.favorites-header .view-subtitle {
  margin-top: 0;
}

/* ---------- Explore ---------- */
.explore-controls {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-top: 1.5rem;
}

.explore-controls .search-field {
  max-width: 100%;
}

.dietary-disclaimer {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-top: 1rem;
  line-height: 1.5;
}

/* ---------- Product Grid ---------- */
.product-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
}

.product-grid > * {
  min-width: 0;
}

@media (min-width: 480px) and (max-width: 1023px) {
  .product-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 1.25rem;
  }
}

@media (min-width: 1024px) {
  .product-grid {
    grid-template-columns: repeat(4, 1fr);
    gap: 1.5rem;
  }
}

.product-card {
  display: flex;
  flex-direction: column;
  padding: 1rem;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;
  text-align: left;
  width: 100%;
  font-family: var(--font-body);
  color: var(--text-primary);
  appearance: none;
  cursor: pointer;
  min-height: 120px;
}

.product-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
  border-color: var(--border-strong);
}

.product-card:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: 2px;
}

.product-card-body {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex: 1;
  min-width: 0;
}

.product-card-main {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.25rem;
  background: none;
  border: none;
  font-family: inherit;
  font-size: inherit;
  color: inherit;
  cursor: pointer;
  padding: 0;
  text-align: left;
  width: 100%;
  appearance: none;
  min-width: 0;
}

.product-card-main:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

.product-card-favorite {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.product-emoji {
  font-size: 2rem;
  line-height: 1;
  flex-shrink: 0;
}

.product-brand {
  font-weight: 600;
  font-size: 0.9rem;
  word-break: break-word;
}

.product-name {
  font-size: 0.8rem;
  color: var(--text-muted);
  word-break: break-word;
}

.product-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  margin-top: 0.5rem;
}

.product-tags .tag {
  white-space: normal;
  word-break: break-word;
}

.favorite-remove {
  background: none;
  border: none;
  font-family: var(--font-body);
  font-size: 0.75rem;
  color: var(--color-coral);
  cursor: pointer;
  padding: 0.25rem 0;
  text-align: left;
  width: fit-content;
  appearance: none;
  min-height: 2.75rem;
  display: inline-flex;
  align-items: center;
}

.favorite-remove:hover {
  text-decoration: underline;
}

.favorite-remove:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

/* ---------- Recipe Grid ---------- */
.recipe-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.25rem;
}

.recipe-grid > * {
  min-width: 0;
}

@media (min-width: 600px) and (max-width: 1023px) {
  .recipe-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 1.5rem;
  }
}

@media (min-width: 1024px) {
  .recipe-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
  }
}

.recipe-card {
  display: flex;
  flex-direction: column;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: transform 0.2s, box-shadow 0.2s;
  cursor: pointer;
  text-align: left;
  width: 100%;
  font-family: var(--font-body);
  color: var(--text-primary);
  appearance: none;
}

.recipe-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.recipe-card:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: 2px;
}

.recipe-media {
  height: 140px;
  background: var(--bg-surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

@media (min-width: 600px) {
  .recipe-media {
    height: 160px;
  }
}

@media (min-width: 1024px) {
  .recipe-media {
    height: 180px;
  }
}

.recipe-visual {
  font-size: 2.5rem;
  line-height: 1;
}

.recipe-body {
  padding: 0.75rem 1rem 1rem;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.recipe-title {
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text-primary);
}

.recipe-meta {
  font-size: 0.8rem;
  color: var(--text-muted);
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
}

/* ---------- Learn ---------- */
.learn-list {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  margin-top: 2rem;
}

.learn-item {
  border-bottom: 1px solid var(--border-subtle);
  padding-bottom: 1.25rem;
}

.learn-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  font-family: var(--font-body);
  appearance: none;
  padding: 0.25rem 0;
  min-height: 2.75rem;
}

.learn-toggle:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

.learn-title {
  font-family: var(--font-display);
  font-size: 1.15rem;
  color: var(--text-primary);
  flex: 1;
}

.learn-arrow {
  font-size: 1.2rem;
  color: var(--text-muted);
  transition: transform 0.25s;
  flex-shrink: 0;
  margin-left: 1rem;
}

.learn-arrow.rotate {
  transform: rotate(180deg);
}

.learn-content {
  margin-top: 0.75rem;
  color: var(--text-secondary);
  font-size: 0.95rem;
  line-height: 1.7;
}

.learn-content p {
  margin-bottom: 0.75rem;
}

.learn-content ul,
.learn-content ol {
  padding-left: 1.5rem;
  margin-bottom: 0.75rem;
}

.learn-content li {
  margin-bottom: 0.25rem;
}

.learn-content strong {
  color: var(--text-primary);
}

/* ---------- Animals ---------- */
.animals-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.animal-count {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.animal-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  margin-top: 1rem;
}

.animal-grid > * {
  min-width: 0;
}

@media (min-width: 600px) and (max-width: 1023px) {
  .animal-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .animal-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.animal-card {
  display: flex;
  flex-direction: column;
  padding: 1.25rem;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;
  text-align: left;
  width: 100%;
  font-family: var(--font-body);
  color: var(--text-primary);
  appearance: none;
  min-height: 150px;
}

.animal-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
  border-color: var(--color-moss);
}

.animal-card:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: 2px;
}

.animal-emoji {
  font-size: 2.5rem;
  line-height: 1;
}

.animal-name {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 600;
  margin-top: 0.25rem;
}

.animal-summary {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-top: 0.25rem;
  flex: 1;
}

.animal-meta {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-top: 0.75rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
}

.sensitive-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
