  text-transform: uppercase;
  letter-spacing: 0.03em;
  background: var(--color-coral);
  color: #27130e;
}

[data-theme="dark"] .sensitive-badge {
  color: #fff;
}

/* ---------- Journey ---------- */
.progress-card {
  background: var(--bg-surface);
  padding: 1.25rem 1.5rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-subtle);
  margin: 1.5rem 0;
}

.progress-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-weight: 500;
}

.progress-label {
  color: var(--text-secondary);
}

.progress-value {
  color: var(--text-primary);
  font-weight: 600;
}

.progress-bar {
  width: 100%;
  height: 0.5rem;
  background: var(--bg-surface-alt);
  border-radius: var(--radius-full);
  margin-top: 0.5rem;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: var(--color-lime);
  border-radius: var(--radius-full);
  transition: width 0.4s ease;
}

.task-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-top: 1rem;
}

.task-item {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s;
}

.task-item:hover {
  background: var(--bg-surface-alt);
}

.task-checkbox {
  margin-top: 0.2rem;
  flex-shrink: 0;
  width: 1.1rem;
  height: 1.1rem;
  accent-color: var(--color-lime);
  border-radius: var(--radius-sm);
  border: 1.5px solid var(--border-subtle);
  cursor: pointer;
}

.task-label {
  font-size: 0.95rem;
  color: var(--text-secondary);
  flex: 1;
}

.task-label.done {
  text-decoration: line-through;
  color: var(--text-muted);
}

/* ---------- Everyday Products ---------- */
.everyday-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  margin-top: 1.5rem;
}

.everyday-grid > * {
  min-width: 0;
}

@media (min-width: 600px) and (max-width: 1023px) {
  .everyday-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .everyday-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.everyday-card {
  padding: 1rem;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.everyday-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.everyday-emoji {
  font-size: 1.75rem;
  line-height: 1;
  flex-shrink: 0;
}

.everyday-name {
  font-weight: 600;
  font-size: 0.95rem;
}

.everyday-desc {
  font-size: 0.8rem;
  color: var(--text-muted);
}

.everyday-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
}

.location-title {
  font-family: var(--font-display);
  font-size: 1.4rem;
  color: var(--text-primary);
  margin-top: 1rem;
}

.location-desc {
  color: var(--text-secondary);
  font-size: 0.95rem;
  margin-top: 0.25rem;
}

/* ---------- Ingredient Library ---------- */
.ingredient-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  margin-top: 1.5rem;
}

.ingredient-grid > * {
  min-width: 0;
}

@media (min-width: 768px) {
  .ingredient-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.ingredient-card {
  padding: 1rem 1.25rem;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
}

.ingredient-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.ingredient-name {
  font-family: var(--font-mono);
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text-primary);
}

.ingredient-aliases {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-left: 0.4rem;
}

.ingredient-source,
.ingredient-found {
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-top: 0.25rem;
}

.ingredient-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  margin-top: 0.5rem;
}

/* ---------- Tags ---------- */
.tag {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.2rem 0.7rem;
  border-radius: var(--radius-full);
  font-size: 0.7rem;
  font-weight: 500;
  background: var(--bg-surface-alt);
  color: var(--text-secondary);
  border: 1px solid var(--border-subtle);
  white-space: nowrap;
}

.tag-lime {
  background: var(--color-lime);
  color: #000;
  border-color: var(--color-lime);
}

.tag-coral {
  background: var(--color-coral);
  color: #27130e;
  border-color: var(--color-coral);
}

[data-theme="dark"] .tag-coral {
  color: #fff;
}

.tag-high-protein {
  background: var(--color-lime);
  color: #000;
  border-color: var(--color-lime);
}

/* ---------- Nutrition ---------- */
.nutrient-list {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  margin-top: 1.5rem;
}

.nutrient-card {
  padding: 1.25rem 1.5rem;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
}

.nutrient-title {
  font-family: var(--font-display);
  font-size: 1.2rem;
  color: var(--text-primary);
}

.nutrient-desc {
  color: var(--text-secondary);
  font-size: 0.95rem;
  margin-top: 0.25rem;
}

.nutrient-details {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.5rem;
  margin-top: 0.75rem;
  font-size: 0.9rem;
}

@media (min-width: 768px) {
  .nutrient-details {
    grid-template-columns: 1fr 1fr;
  }
}

.nutrient-label {
  font-weight: 600;
  color: var(--text-secondary);
}

.nutrient-disclaimer {
  margin-top: 0.75rem;
  padding: 0.5rem 0.75rem;
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  color: var(--text-muted);
}

.nutrition-note {
  margin-top: 1.5rem;
  padding: 1rem 1.25rem;
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  font-size: 0.9rem;
  color: var(--text-secondary);
}

.nutrition-note-strong {
  font-weight: 600;
  color: var(--text-primary);
}

/* ---------- About ---------- */
.about-content {
  margin-top: 1.5rem;
  color: var(--text-secondary);
  font-size: 0.95rem;
  line-height: 1.7;
}

.about-content p {
  margin-bottom: 1rem;
}

.about-content hr {
  border: none;
  border-top: 1px solid var(--border-subtle);
  margin: 1.5rem 0;
}

.about-content strong {
  color: var(--text-primary);
}

.companion-project {
  margin: 1.5rem 0;
  padding: 1.25rem;
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
}

.companion-project-label {
  margin-bottom: 0.35rem !important;
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.companion-project h3 {
  margin-bottom: 0.5rem;
  color: var(--text-primary);
  font-size: 1.25rem;
}

.companion-project-link {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  color: var(--primary);
  font-weight: 700;
}

.about-disclaimer {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-top: 1rem;
}

/* ---------- Empty State ---------- */
.empty-state {
  text-align: center;
  padding: 3rem 1rem;
  color: var(--text-muted);
  font-size: 1rem;
}

.empty-state span {
  font-size: 3rem;
  display: block;
  margin-bottom: 0.5rem;
}

.empty-text {
  color: var(--text-muted);
  font-size: 0.9rem;
  margin-top: 0.5rem;
}

/* ---------- Filter Row ---------- */
.filter-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.75rem;
  margin-bottom: 0.75rem;
}

.filter-row .filter-chip {
  flex-shrink: 0;
}

.recipe-filter-panel {
  display: grid;
  gap: 0.65rem;
  margin: 0.9rem 0;
}

.recipe-filter-group {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: 0.45rem;
  min-width: 0;
}

.recipe-filter-label {
  width: 4.5rem;
  flex: 0 0 4.5rem;
  color: var(--text-muted);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.recipe-filter-scroll {
  display: flex;
  flex: 1 1 auto;
  flex-wrap: nowrap;
  align-items: center;
  gap: 0.45rem;
  min-width: 0;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 0.15rem 0 0.45rem;
  scroll-behavior: smooth;
  scrollbar-width: thin;
  scrollbar-color: var(--border-strong) transparent;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior-inline: contain;
}

.recipe-filter-scroll > * {
  flex: 0 0 auto;
}

.recipe-filter-scroll::-webkit-scrollbar {
  height: 0.4rem;
}

.recipe-filter-scroll::-webkit-scrollbar-track {
  background: transparent;
}

.recipe-filter-scroll::-webkit-scrollbar-thumb {
  background: var(--border-strong);
  border-radius: var(--radius-full);
}

.recipe-filter-scroll:focus-visible {
  outline: 2px solid var(--color-lime);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

.filter-clear {
  border: 0;
  background: transparent;
  color: var(--primary);
  cursor: pointer;
  font: inherit;
  font-size: 0.82rem;
  font-weight: 700;
  padding: 0.4rem 0.2rem;
}

.filter-clear:hover,
.filter-clear:focus-visible {
  text-decoration: underline;
}

@media (max-width: 520px) {
  .recipe-filter-group {
    flex-wrap: wrap;
  }

  .recipe-filter-label {
    width: 100%;
    flex-basis: 100%;
  }

  .recipe-filter-scroll {
    flex-basis: 100%;
    width: 100%;
  }
}

/* ---------- Modals ---------- */
.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: var(--bg-overlay);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 0;
}

@media (min-width: 1024px) {
  .modal-overlay {
    align-items: center;
    padding: 1.5rem;
  }
}

.modal-panel {
  background: var(--bg-elevated);
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  max-width: 100%;
  width: 100%;
  max-height: 92vh;
  overflow-y: auto;
  padding: 1.5rem;
  border: 1px solid var(--border-subtle);
  border-bottom: none;
  box-shadow: var(--shadow-modal);
  transition: background 0.25s;
  margin-top: auto;
}

@media (min-width: 1024px) {
  .modal-panel {
    border-radius: var(--radius-lg);
    max-width: 640px;
    padding: 2rem;
    border: 1px solid var(--border-subtle);
    margin-top: 0;
  }
}

.modal-panel-wide {
  max-width: 900px;
}

.modal-close {
  float: right;
  font-size: 1.75rem;
  color: var(--text-muted);
  background: none;
  border: none;
  cursor: pointer;
  transition: color 0.2s;
  line-height: 1;
  padding: 0.25rem;
  appearance: none;
  min-height: 2.75rem;
  min-width: 2.75rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.modal-close:hover {
  color: var(--text-primary);
}

.modal-close:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

/* ---------- Modal Tabs ---------- */
/* Default: horizontal scroll with hidden scrollbar (for larger screens) */
.modal-tabs {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  gap: 0.25rem;
  border-bottom: 1px solid var(--border-subtle);
  padding-bottom: 0.25rem;
  margin: 1rem 0 1.25rem;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.modal-tabs::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

.modal-tab {
  flex: 0 0 auto;
  padding: 0.4rem 1rem;
  font-size: 0.85rem;
  font-weight: 500;
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--text-secondary);
  cursor: pointer;
  transition: color 0.2s, border-color 0.2s;
  font-family: var(--font-body);
  appearance: none;
  white-space: nowrap;
  min-height: 2.75rem; /* 44px */
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  scroll-snap-align: start;
}

.modal-tab:hover {
  color: var(--text-primary);
}

.modal-tab:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: -2px;
  border-radius: var(--radius-sm);
}

.modal-tab.active {
  color: var(--color-forest);
  border-bottom-color: var(--color-forest);
}

[data-theme="dark"] .modal-tab.active {
  color: var(--color-forest);
  border-bottom-color: var(--color-forest);
}

/* Mobile: wrap tabs into multiple clean rows, no scroll, no clipping */
@media (max-width: 1023px) {
  .modal-tabs {
    flex-wrap: wrap;
    overflow: visible;
    scroll-snap-type: none;
    scroll-behavior: auto;
    gap: 0.5rem 0.25rem;
    justify-content: center;
  }
  .modal-tab {
    flex: 0 1 auto;
    white-space: nowrap;
    scroll-snap-align: none;
    min-height: 44px;
    padding: 0.4rem 0.75rem;
  }
}

/* ---------- Modal Body ---------- */
.modal-body {
  display: none;
  animation: modalFade 0.2s ease;
}

.modal-body.active {
  display: block;
}

@keyframes modalFade {
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}

.modal-text {
  color: var(--text-secondary);
  line-height: 1.6;
}

.modal-subtitle {
  font-family: var(--font-display);
  font-size: 1.1rem;
  color: var(--text-primary);
  margin-top: 1.25rem;
  margin-bottom: 0.5rem;
}

.modal-list {
  list-style: disc;
  padding-left: 1.5rem;
  color: var(--text-secondary);
  font-size: 0.9rem;
}

.modal-list li {
  margin-bottom: 0.25rem;
}

.modal-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  margin-top: 0.25rem;
}

/* ---------- Animal Detail Modal ---------- */
.animal-detail-header {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 0.5rem;
}

.animal-detail-emoji {
  font-size: 3rem;
  line-height: 1;
  flex-shrink: 0;
}

.animal-detail-name {
  font-family: var(--font-display);
  font-size: 1.6rem;
  color: var(--text-primary);
}

.animal-detail-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.25rem;
}

/* ---------- Detail Grid (Natural Life) ---------- */
.detail-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.6rem;
}

.detail-grid > * {
  min-width: 0;
}

@media (min-width: 1024px) {
  .detail-grid {
    grid-template-columns: 1fr 1fr;
    gap: 0.75rem 1.5rem;
  }
}

.detail-row {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  flex-wrap: wrap;
  font-size: 0.95rem;
  color: var(--text-secondary);
  min-width: 0;
}

.detail-label {
  font-weight: 600;
  color: var(--text-primary);
  flex-shrink: 0;
}

.detail-row span:last-child {
  word-break: normal;
  overflow-wrap: break-word;
  min-width: 0;
}

/* ---------- Uses ---------- */
.use-list {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-top: 0.5rem;
}

.use-card {
  padding: 0.75rem 1rem;
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
}

.use-title {
  font-weight: 600;
  font-size: 1rem;
  color: var(--text-primary);
}

.use-summary {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-top: 0.15rem;
}

.use-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  margin-top: 0.5rem;
}

/* ---------- Ingredient Rows ---------- */
.ingredient-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-top: 0.5rem;
}

.ingredient-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
}

.ingredient-row .ingredient-name {
  font-family: var(--font-mono);
  font-weight: 500;
  font-size: 0.9rem;
}

.ingredient-row-tags {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.ingredient-found-in {
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* ---------- Alternatives ---------- */
.alt-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.75rem;
  margin-top: 0.5rem;
}

@media (min-width: 600px) {
  .alt-grid {
    grid-template-columns: 1fr 1fr;
  }
}

.alt-card {
  padding: 0.75rem 1rem;
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
}

.alt-name {
  font-weight: 600;
  color: var(--text-primary);
}

.alt-desc {
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-top: 0.1rem;
}

.alt-placeholder {
  padding: 1rem;
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  color: var(--text-secondary);
  margin-top: 0.5rem;
}

.alt-tip {
  font-weight: 600;
  color: var(--text-primary);
}

.alt-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1.25rem;
}

@media (max-width: 479px) {
  .alt-actions .secondary-button {
    width: 100%;
    justify-content: center;
  }
}

/* ---------- Sources ---------- */
.source-list {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-top: 0.5rem;
}

.source-card {
  padding: 0.75rem 1rem;
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
}

.source-title {
  font-weight: 600;
  color: var(--text-primary);
}

.source-org {
  font-size: 0.85rem;
  color: var(--text-secondary);
}

.source-date {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.source-link {
  display: inline-block;
  margin-top: 0.25rem;
  color: var(--color-moss);
  font-size: 0.9rem;
  text-decoration: none;
}

.source-link:hover {
  text-decoration: underline;
}

/* ---------- Product Detail Modal ---------- */
.product-detail-title {
  font-family: var(--font-display);
  font-size: 1.5rem;
  color: var(--text-primary);
  margin-bottom: 0.5rem;
}

.product-detail-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}

.product-detail-desc {
  color: var(--text-secondary);
  margin: 0.75rem 0;
}

.product-detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.5rem 1rem;
  font-size: 0.9rem;
  color: var(--text-secondary);
}

.product-detail-meta {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-top: 0.25rem;
}

.product-detail-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

@media (max-width: 479px) {
  .product-detail-actions .secondary-button {
    width: 100%;
    justify-content: center;
  }
}

/* ---------- Recipe Detail Modal ---------- */
.recipe-detail-title {
  font-family: var(--font-display);
  font-size: 1.5rem;
  color: var(--text-primary);
}

.recipe-detail-desc {
  color: var(--text-secondary);
  margin-top: 0.25rem;
}

.recipe-detail-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin: 0.75rem 0 1.25rem;
}

.recipe-detail-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

.recipe-detail-grid > * {
  min-width: 0;
}

@media (min-width: 1024px) {
  .recipe-detail-grid {
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
  }
}

.recipe-detail-subtitle {
  font-family: var(--font-display);
  font-size: 1.1rem;
  color: var(--text-primary);
  margin-bottom: 0.5rem;
}

.recipe-ingredient-list {
  list-style: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  font-size: 0.9rem;
  color: var(--text-secondary);
}

.recipe-ingredient-list li {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.recipe-ingredient-list .task-checkbox {
  margin-top: 0;
}

.recipe-instruction-list {
  padding-left: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  font-size: 0.9rem;
  color: var(--text-secondary);
}

/* ---------- Ingredient Detail Modal ---------- */
.ingredient-detail-title {
  font-family: var(--font-display);
  font-size: 1.5rem;
  color: var(--text-primary);
}

.ingredient-detail-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin: 0.5rem 0 1rem;
}

.ingredient-detail-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.5rem;
  font-size: 0.9rem;
  color: var(--text-secondary);
}

.ingredient-detail-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

@media (max-width: 479px) {
  .ingredient-detail-actions .secondary-button {
    width: 100%;
    justify-content: center;
  }
}

/* ---------- Ingredient Checker ---------- */
.checker-title {
  font-family: var(--font-display);
  font-size: 1.5rem;
  color: var(--text-primary);
}

.checker-subtitle {
  color: var(--text-secondary);
  font-size: 0.95rem;
  margin-top: 0.25rem;
}

.checker-textarea {
  width: 100%;
  padding: 0.75rem 1rem;
  margin-top: 1rem;
  background: var(--bg-input);
  color: var(--text-primary);
  border: 1.5px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  font-family: var(--font-body);
  font-size: 0.95rem;
  resize: vertical;
  min-height: 120px;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.checker-textarea:focus {
  outline: none;
  border-color: var(--color-moss);
  box-shadow: 0 0 0 3px rgba(109, 139, 97, 0.15);
}

.checker-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1rem;
}

.checker-actions .text-button {
  align-self: center;
}

@media (max-width: 479px) {
  .checker-actions .primary-button,
  .checker-actions .secondary-button {
    width: 100%;
    justify-content: center;
  }
}

.checker-results {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-top: 1.25rem;
}

.checker-result {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 1rem;
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-sm);
  border-left: 4px solid transparent;
  font-size: 0.9rem;
  background: var(--bg-surface-alt);
}

.checker-result.animal {
  border-left-color: var(--color-coral);
  background: rgba(233, 130, 105, 0.08);
}

.checker-result.usually {
  border-left-color: #e8b84a;
  background: rgba(232, 184, 74, 0.08);
}

.checker-result.maybe {
  border-left-color: #8a9ba8;
  background: rgba(138, 155, 168, 0.08);
}

.checker-result.clear {
  border-left-color: var(--color-moss);
  background: rgba(109, 139, 97, 0.08);
}

.checker-result.unknown {
  border-left-color: var(--border-strong);
  background: var(--bg-surface-alt);
}

.checker-result-term {
  font-family: var(--font-mono);
  font-weight: 500;
  flex: 1 1 auto;
  min-width: 100px;
  color: var(--text-primary);
}

.checker-result-status {
  font-weight: 600;
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 0.1rem 0.6rem;
  border-radius: var(--radius-full);
  flex-shrink: 0;
}

.checker-result-status.animal {
  background: var(--color-coral);
  color: #27130e;
}

[data-theme="dark"] .checker-result-status.animal {
  color: #fff;
}

.checker-result-status.usually {
  background: #e8b84a;
  color: #27130e;
}

[data-theme="dark"] .checker-result-status.usually {
  color: #fff;
}

.checker-result-status.maybe {
  background: #8a9ba8;
  color: #fff;
}

.checker-result-status.clear {
  background: var(--color-moss);
  color: var(--text-inverse);
}

.checker-result-status.unknown {
  background: var(--border-strong);
  color: var(--text-inverse);
}

.checker-result-note {
  font-size: 0.8rem;
  color: var(--text-muted);
  flex: 1 1 100%;
}

@media (min-width: 600px) {
  .checker-result-note {
    flex: 0 1 auto;
  }
}

.checker-disclaimer {
  margin-top: 1rem;
  padding: 0.75rem 1rem;
  background: var(--bg-surface-alt);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  color: var(--text-muted);
}

.checker-disclaimer span {
  display: inline-block;
  margin-right: 0.25rem;
}

/* ---------- Bottom Navigation ---------- */
.bottom-navigation {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 50;
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-around;
  padding: 0.4rem 0 env(safe-area-inset-bottom, 0.5rem);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.bottom-nav-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  padding: 0.25rem 0.5rem;
  font-size: 0.6rem;
  font-weight: 500;
  color: var(--text-muted);
  background: none;
  border: none;
  cursor: pointer;
  transition: color 0.2s;
  min-width: 3rem;
  position: relative;
  font-family: var(--font-body);
  appearance: none;
  min-height: 2.75rem;
  justify-content: center;
}

.bottom-nav-item .nav-icon {
  font-size: 1.2rem;
  line-height: 1;
}

.bottom-nav-item.active {
  color: var(--text-primary);
}

.bottom-nav-item.active::after {
  content: '';
  position: absolute;
  top: -2px;
  left: 30%;
  width: 40%;
  height: 3px;
  background: var(--color-forest);
  border-radius: 0 0 4px 4px;
}

.bottom-nav-item:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

@media (min-width: 1024px) {
  .bottom-navigation {
    display: none !important;
  }
}

/* ---------- More Drawer ---------- */
.more-drawer {
  position: fixed;
  bottom: calc(4.5rem + env(safe-area-inset-bottom, 0px));
  right: 0.75rem;
  z-index: 49;
  background: var(--bg-elevated);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  padding: 0.5rem;
  min-width: 180px;
  display: block;
  pointer-events: none;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity 0.2s, transform 0.2s, visibility 0.2s;
  visibility: hidden;
}

.more-drawer.open {
  pointer-events: auto;
  opacity: 1;
  transform: translateY(0);
  visibility: visible;
}

.more-drawer button,
.more-drawer > a {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.6rem 1rem;
  width: 100%;
  background: none;
  border: none;
  border-radius: var(--radius-sm);
  font-family: var(--font-body);
  font-size: 0.85rem;
  color: var(--text-secondary);
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
  text-align: left;
  appearance: none;
  min-height: 2.75rem;
  text-decoration: none;
}

.more-drawer button:hover,
.more-drawer > a:hover {
  background: var(--bg-surface-alt);
  color: var(--text-primary);
}

.more-drawer button:focus-visible,
.more-drawer > a:focus-visible {
  outline: 3px solid var(--color-lime);
  outline-offset: -2px;
}

.more-drawer .drawer-icon {
  font-size: 1.1rem;
  line-height: 1;
}

@media (min-width: 1024px) {
  .more-drawer {
    display: none !important;
  }
}

/* ---------- Footer ---------- */
.app-footer {
  text-align: center;
  font-size: 0.75rem;
  color: var(--text-muted);
  padding: 2rem 1.25rem;
  border-top: 1px solid var(--border-subtle);
  margin-top: 1rem;
}

@media (max-width: 1023px) {
  .app-footer {
    padding-bottom: calc(5rem + env(safe-area-inset-bottom, 0px));
  }
}

.footer-disclaimer {
  margin-top: 0.25rem;
  font-size: 0.7rem;
}

/* ---------- Toast ---------- */
.toast-container {
  position: fixed;
  bottom: calc(5.5rem + env(safe-area-inset-bottom, 0px));
  left: 50%;
  transform: translateX(-50%);
  z-index: 999;
  pointer-events: none;
  max-width: 90vw;
  width: auto;
}

@media (min-width: 768px) {
  .toast-container {
    bottom: 2rem;
  }
}

@media (min-width: 1024px) {
  .toast-container {
    bottom: 2rem;
  }
}

.toast {
  background: var(--bg-elevated);
  color: var(--text-primary);
  border: 1px solid var(--border-subtle);
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-lg);
  font-weight: 500;
  pointer-events: auto;
  cursor: pointer;
  animation: toastIn 0.35s ease forwards;
  font-size: 0.95rem;
}

@keyframes toastIn {
  0% { opacity: 0; transform: translateY(20px) scale(0.96); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

/* ---------- Skip Link ---------- */
.skip-link {
  position: absolute;
  top: -1000px;
  left: 1rem;
  padding: 0.75rem 1.5rem;
  background: var(--color-forest);
  color: var(--text-inverse);
  z-index: 9999;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
}

.skip-link:focus {
  top: 1rem;
}

/* ---------- Reduced Motion ---------- */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* ---------- Helpers ---------- */
.line-through {
  text-decoration: line-through;
}

.rotate-180 {
  transform: rotate(180deg);
}

/* ============================================================
   FINAL CORRECTIONS
   ============================================================ */

/* Keep tablet toast above fixed bottom navigation */
@media (min-width: 768px) and (max-width: 1023px) {
  .toast-container {
    bottom: calc(5.5rem + env(safe-area-inset-bottom, 0px));
  }
}

/* Use dynamic viewport height and mobile safe-area spacing */
.modal-panel {
  max-height: 92vh;
  max-height: 92dvh;
  padding-bottom: calc(1.5rem + env(safe-area-inset-bottom, 0px));
}

@media (min-width: 1024px) {
  .modal-panel {
    padding-bottom: 2rem;
  }
}

/* Keep mobile hero search icon, input, and button aligned */
@media (max-width: 479px) {
  .hero-search .search-field {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: center;
  }

  .hero-search .search-icon {
    grid-column: 1;
    grid-row: 1;
  }

  .hero-search .search-input {
    grid-column: 2;
    grid-row: 1;
    min-width: 0;
  }

  .hero-search .search-submit {
    grid-column: 1 / -1;
    grid-row: 2;
    width: 100%;
  }
}

/* Prevent product modal details from becoming cramped */
@media (max-width: 599px) {
  .product-detail-grid {
    grid-template-columns: 1fr;
  }
}

/* Product verification statuses returned by JavaScript */
.status-certified {
  background: var(--color-lime);
  border-color: var(--color-lime);
  color: #102117;
}

.status-labeled {
  background: rgba(184, 225, 75, 0.22);
  border-color: var(--color-lime);
  color: var(--text-primary);
}

.status-verify {
  background: rgba(232, 184, 74, 0.2);
  border-color: #c99525;
  color: var(--text-primary);
}

.status-unknown {
  background: var(--bg-surface-alt);
  border-color: var(--border-strong);
  color: var(--text-secondary);
}

/* Keep long modal tags inside the viewport */
.modal-tags .tag,
.product-detail-tags .tag,
.ingredient-detail-tags .tag,
.animal-detail-tags .tag {
  max-width: 100%;
  white-space: normal;
  overflow-wrap: break-word;
}

[data-theme="light"] button.primary-button,
[data-theme="dark"] button.primary-button {
  background-color: var(--color-forest);
  color: var(--text-inverse);
}

[data-theme="light"] button.primary-button:hover,
[data-theme="dark"] button.primary-button:hover {
  background-color: var(--color-forest-hover);
}

/* Center mobile/tablet modals while keeping tall content visible */
@media (max-width: 1023px) {
  .modal-overlay {
    width: 100%;
    height: 100vh;
    height: 100dvh;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;

    padding:
      max(1rem, env(safe-area-inset-top, 0px))
      1rem
      max(1rem, env(safe-area-inset-bottom, 0px));
  }

  .modal-panel {
    width: 100%;
    max-width: 900px;
    max-height: calc(
      100dvh - 2rem -
      env(safe-area-inset-top, 0px) -
      env(safe-area-inset-bottom, 0px)
    );

    margin: 0;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;

    border: 1px solid var(--border-subtle);
    border-radius: var(--radius-lg);

    padding: 1.5rem;
    padding-bottom: calc(
      1.5rem + env(safe-area-inset-bottom, 0px)
    );
  }
}

