ource-description{font-size:.88rem;line-height:1.55;color:var(--text-secondary);margin:0}.resource-content-warning{font-size:.78rem;line-height:1.45;padding:.7rem;margin-top:.8rem;border-radius:.7rem;background:color-mix(in srgb,#d96c5a 9%,var(--bg-surface-alt));color:var(--text-secondary)}.resource-tags{display:flex;flex-wrap:wrap;gap:.35rem;margin:.9rem 0}.resource-tags span{font-size:.68rem;padding:.24rem .42rem;border-radius:.45rem;background:var(--bg-surface-alt);color:var(--text-muted)}.resource-open-link{display:flex;align-items:center;justify-content:space-between;gap:.6rem;margin-top:auto;padding-top:.8rem;color:var(--color-moss);font-weight:700;text-decoration:none;border-top:1px solid var(--border-subtle)}.resource-open-link:hover{text-decoration:underline}.resource-disclaimer{max-width:52rem;margin:1.4rem auto 0;text-align:center;color:var(--text-muted);font-size:.78rem;line-height:1.5}@media(max-width:960px){.resource-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:640px){.resources-heading{align-items:flex-start;flex-direction:column}.resource-grid{grid-template-columns:1fr}.external-resource-card{padding:1rem}}


