rce-list a,.evidence-related-list button{display:flex;justify-content:space-between;align-items:center;gap:.75rem;text-align:left;padding:.8rem;border:1px solid var(--border-color);border-radius:12px;background:var(--bg-surface);color:var(--text-primary);text-decoration:none;font-weight:650}.evidence-related-list button{cursor:pointer}.secondary-button{margin-top:.7rem}
