ation-question span{color:var(--text-secondary);line-height:1.55}.normalization-actions{display:flex;gap:.65rem;flex-wrap:wrap;margin-top:1rem}.normalization-reflection{padding:1.25rem;border-radius:18px;border:1px solid var(--border);background:var(--bg-card)}.normalization-reflection blockquote{margin:.6rem 0 1rem;font-size:1.25rem;line-height:1.45;font-weight:750}.normalization-reflection p{margin:0;color:var(--text-secondary);line-height:1.6}@media(max-width:720px){.normalization-grid,.normalization-mechanism-grid{grid-template-columns:1fr}.normalization-heading{gap:.7rem}.normalization-card{padding:.9rem}.normalization-question p,.normalization-reflection blockquote{font-size:1.08rem}.normalization-actions{display:grid}.normalization-actions button{width:100%}}


/* ---------- Tiny-screen reflow audit (320 CSS px baseline) ---------- */
html, body { max-width: 100%; overflow-x: hidden; }
.app-shell, .view-container, main, section { min-width: 0; }
img, svg, video, canvas { max-width: 100%; }
.tiny-share-menu-item { display: none !important; }
.evidence-shell, .evidence-landing, .evidence-hero, .evidence-hero-copy,
.evidence-search-box, .evidence-results, .evidence-detail { min-width: 0; max-width: 100%; }
.evidence-search-box input { min-width: 0; max-width: 100%; }

@media (max-width: 360px) {
  .header-inner { padding-left: .65rem; padding-right: .65rem; gap: .35rem; }
  .brand { gap: .3rem; min-width: 0; }
  .brand-name { font-size: 1.05rem; white-space: nowrap; }
  .brand-icon { font-size: 1.25rem; }
  .header-actions { gap: .05rem; }
  .icon-button { width: 2.5rem; min-width: 2.5rem; height: 2.75rem; padding: 0; }
  /* Preserve Share immediately before Donate on normal phones; move it into More only when space is truly tight. */
  .header-share-button { display: none !important; }
  .tiny-share-menu-item { display: flex !important; }

  .view-container { padding-left: .75rem; padding-right: .75rem; }
  .evidence-hero { display: grid; grid-template-columns: minmax(0,1fr); gap: .65rem; }
  .evidence-hero-copy { width: 100%; }
  .evidence-hero h1 { font-size: clamp(2rem, 11vw, 2.65rem); line-height: 1.02; overflow-wrap: anywhere; }
  .evidence-search-box { width: 100%; box-sizing: border-box; padding-left: .65rem; padding-right: .45rem; }
  .evidence-search-box input { width: 100%; font-size: .95rem; }
  .evidence-category-strip { flex-wrap: wrap; overflow-x: visible; gap: .45rem; padding-bottom: .2rem; }
  .evidence-category-chip { white-space: normal; flex: 0 1 auto; padding: .5rem .68rem; font-size: .88rem; }

  .bottom-navigation { justify-content: stretch; padding-left: .15rem; padding-right: .15rem; }
  .bottom-nav-item { flex: 1 1 0; min-width: 0; padding-left: .1rem; padding-right: .1rem; font-size: .55rem; }
  .bottom-nav-item .nav-icon { font-size: 1.08rem; }
  .more-drawer { left: .5rem; right: .5rem; width: auto; max-width: none; }
}

@media (max-width: 330px) {
  .header-inner { padding-left: .45rem; padding-right: .45rem; }
  .brand-name { font-size: .98rem; }
  .icon-button { width: 2.35rem; min-width: 2.35rem; }
  .view-container { padding-left: .6rem; padding-right: .6rem; }
  .bottom-nav-item { font-size: .51rem; }
  .bottom-nav-item .nav-icon { font-size: 1rem; }
}

/* Header action links must retain button styling, never browser link underlines. */
.icon-button, .icon-button:hover, .icon-button:focus, .icon-button:active, .icon-button:visited { text-decoration: none; }

