  function makeRecipeArtwork(title, emoji) {
    const safeTitle = String(title).replace(/[&<>"']/g, character => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&apos;' }[character]));
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="800" height="500" viewBox="0 0 800 500"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#123c2e"/><stop offset="1" stop-color="#6d8b61"/></linearGradient></defs><rect width="800" height="500" fill="url(#g)"/><circle cx="400" cy="195" r="112" fill="#f7f2e8" opacity=".14"/><text x="400" y="235" text-anchor="middle" font-size="118">${emoji}</text><text x="400" y="390" text-anchor="middle" fill="#fffdf7" font-family="Arial,sans-serif" font-size="38" font-weight="700">${safeTitle}</text></svg>`;
    return `data:image/svg+xml;base64,${btoa(unescape(encodeURIComponent(svg)))}`;
  }

